def transform(grid):
    out = [row[:] for row in grid]
    for i, row in enumerate(grid):
        if row[-1] == 5 and 2 in row:
            c = row.index(2)
            for j in range(c + 1, len(row) - 1):
                out[i][j] = 2
            out[i][c] = 4
    return out
